def broadcast_shape(a, b):
    # Align shapes from the right; sizes must be equal or one of them 1
    n = max(len(a), len(b))
    a = (1,) * (n - len(a)) + tuple(a)
    b = (1,) * (n - len(b)) + tuple(b)
    out = []
    for x, y in zip(a, b):
        if x != y and x != 1 and y != 1:
            raise ValueError("shapes %s and %s are not compatible" % (a, b))
        out.append(max(x, y))
    return tuple(out)

pairs = [((3, 4), (4,)), ((3, 1), (1, 4)), ((3, 4), (3,)), ((100,), (100, 1))]
for a, b in pairs:
    try:
        print(a, "+", b, "->", broadcast_shape(a, b))
    except ValueError as err:
        print(a, "+", b, "-> error:", err)

# The silent bug: (100,) - (100,1) becomes (100,100)
shape = broadcast_shape((100,), (100, 1))
print("loss terms computed:", shape[0] * shape[1], "instead of 100")
print("bytes for float64 result:", shape[0] * shape[1] * 8)
